// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, 1 ether);

        address funder = address(0xBEEF);
        vm.deal(funder, 10 ether);
        vm.startPrank(funder);
        (bool s,) = address(c).call{value: 1 ether}("");
        require(s);
        vm.stopPrank();

        Reverter rev = new Reverter();

        uint256 cBal = address(c).balance;
        vm.assume(cBal >= 0);
        amount = bound(amount, 0, cBal);

        SimpleWallet c2;
        vm.prank(address(rev));
        c2 = new SimpleWallet();

        vm.deal(address(c2), 1 ether);

        bool ok;
        try rev.callWithdraw(c2, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    receive() external payable {
        revert("no receive");
    }
    fallback() external payable {
        revert("no fallback");
    }
    function callWithdraw(SimpleWallet target, uint256 amount) external {
        target.withdraw(amount);
    }
}
